-- Megaverse in Flames: Soulmancy spells, levels six to nine.
-- 14 spells rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~341-megaverse-in-flames-spells-b.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- Soulmancy, levels six to nine, by the spell list on printed p.91; every level
-- agrees with the description headings (p.96-100) and the Contents (p.5), and
-- every list cost agrees with its description's P.P.E. line. Every cost and stat
-- line was read off a render. Soulmancy: Life Drain carries same_spell_as Life
-- Drain (Rifts Ultimate Edition p.213): same level, cost, range, duration and save.

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Soulmancy: Blood Bolt', 6, 20, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.96', 'rifts', '100 feet (30.5 m) per level of experience', 'Instant', '1D8+2 M.D., plus 1D8 per additional level of experience; the caster takes 1D4 damage per level of the caster as the shard leaves his palm', 'Dodge, or parry with a shield, at -2 and only if the victim knows the bolt is coming', NULL, NULL, 'A blood-slick shard of bone bursts out of the caster''s open palm and flies at a single target, tearing his own hand as it leaves for 1D4 points of damage per caster level. He adds +1 to strike on top of his P.P. bonuses. A target aware of the attack may try to dodge it or catch it on a shield, at -2.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Read Soul in Object', 6, 30, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.96-97', 'rifts', 'Touch; reads souls held in a Soul Crystal, Rune Weapon or other magic object', 'Two minutes per level of the spell caster', NULL, 'Standard, using the trapped soul''s own save from life; on a success nothing is learned, no link forms, and the same object or soul cannot be tried again for 1D4 weeks', NULL, NULL, 'Lets the caster study a disembodied soul held in a Soul Crystal, a Rune or Bio-Wizard weapon or any similar vessel that draws power from a life essence; it also works on an object housing an Entity and on a possessed person. Holding the item and concentrating for 1-4 melee rounds yields what Peer into the Soul would show; two minutes on one soul yields what Reveal Soul would; two minutes more reveal what kind of being it is, what it did in life, who imprisoned it (rarely by name), whether it went willingly, as punishment or as an innocent, and how it feels about its captivity. The caster can also speak mind to mind with an intelligent soul, but nothing makes it truthful, it may lie outright, and the link leaves him open to any psionic powers the object holds; a terrified, mad or tormented soul may give only screams and sobbing. A soul knows nothing beyond the moment it was taken, apart from scraps about whoever now owns it.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Toxic Blood', 6, 30, '30 P.P.E. plus 2 S.D.C. damage per level of the caster, taken directly from his Hit Points', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.97', 'rifts', 'Touch', 'The poison breaks down within 1D6 hours; once swallowed it does harm for one melee round per level of the caster', '1D6 direct to Hit Points (M.D. to a Mega-Damage creature) each melee round, for one melee round per level of the caster', 'Save vs lethal poison, 14 or higher', NULL, NULL, 'With a short incantation and a pricked finger, a Blood Warrior or Soulmancer turns his own blood into one dose of poison. It must be swallowed, or reach an open wound; mere contact with skin does nothing. A victim who fails the save takes damage straight to Hit Points (M.D.C. for a Mega-Damage creature) every round for the duration. An unused dose loses its potency in 1D6 hours.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Oath', 7, 10, '50, or only 10 when the Soulmancer casts it on himself', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.97', 'rifts', 'Self or other by touch', 'Until the oath is fulfilled', 'Special: +1 on all combat bonuses and Perception Rolls while keeping the oath, -2 while straying from it', '13 as a spell, 16 as a ritual; none for one who swears sincerely and willingly; +3 for one forced to swear; none for a Soulmancer binding himself. The caster knows whether a forced swearer saved', NULL, 'Spell or ritual; optionally the swearer touches a drop of his own blood to the person he swears to', 'Seals a promise so it cannot be broken. While working to keep his word the bound person gains +1 to Perception Rolls and to every combat bonus; if he neglects or turns from it he suffers -2 to both instead, though that is rare because the magic drives him toward fulfilment. After 1D6 weeks the drive becomes an obsession that ends only when the promise is kept or the one it was made to releases him. Soulmancers often bind themselves with it to show they will honour their end of a bargain.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Bloody Boils', 7, 25, '25 P.P.E. plus 1D6 S.D.C. damage to the caster', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.97', 'rifts', 'Touch or 20 feet (6.1 m); line of sight required', 'One minute per level of the spell caster', '1D6 S.D.C./Hit Points per melee round from bursting boils (M.D. to a Mega-Damage being)', 'Standard, or -1 if touched; a successful save still spends the P.P.E.', NULL, NULL, 'Raises painful, bleeding boils all over the victim; body armor makes it worse, since every bump and rub bursts them. While the spell lasts he is -4 to strike, dodge and parry, loses one melee attack, and is -10% Spd and -10% on skills, and the broken boils bleed for damage every round. When it ends the boils vanish without a mark, leaving only blood smeared on skin, clothing and the inside of armor.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Create Soulmancy Soul Crystal', 7, 40, '40 P.P.E. plus a precious stone of at least three carats', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.97-98', 'rifts', 'Touch', 'One year per level of the caster, after which the gem cracks and stops working', NULL, 'None', NULL, 'Ritual of 1D4+4 minutes; needs a precious stone of three carats or more', 'Turns a fine gemstone into a Soul Crystal, or soul gem: a vessel that holds one life essence at a time and can be emptied and reused until it cracks. The crystal has 1D6+1 M.D.C. and is too delicate to survive a Permanency ritual. This makes only the empty vessel; putting a soul into it takes a separate and far costlier ritual.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Inflict Internal Trauma', 7, 40, '40 P.P.E. plus 1D6 damage as the caster stabs himself in the abdomen, as a spell; 140 P.P.E. and a blood sacrifice (animal or humanoid) as a ritual', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.98', 'rifts', 'One victim by touch or 5 feet (1.5 m) per level of the spell caster, line of sight required; as a ritual, every enemy within a 100 foot (30.5 m) radius', 'Four melee rounds (one minute) per level of the spell caster', '2D6 per minute (Hit Points/S.D.C., or M.D. to a Mega-Damage being)', 'Standard, or 16 or higher against the ritual; a successful save still spends the P.P.E.', 'As a ritual, a 100 foot (30.5 m) radius around where it was performed', 'Spell, or a four-minute ritual that ends in a blood sacrifice', 'Ruptures blood vessels inside the victim: he bleeds internally, his gut aches, he turns dizzy and sick and coughs up blood. The fear and confusion cost him -1 on every combat roll, -4 on Perception Rolls, one melee attack, 30% of his Spd and 10% on skills, and he takes damage for every minute it lasts. Body armor does not stop it; power armor and armored M.D.C. vehicles do. When it ends, the penalties and bleeding stop but the damage heals at the normal rate, and Bio-Regeneration cannot mend this damage until the duration is over.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Life Drain', 7, 25, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.98', 'rifts', '30 feet (9.1 m)', 'Two melees (30 seconds) per level of experience', 'Special; see description', 'Standard; a success means no effect. Those inside power armor, environmental body armor, manned robots or military vehicles are still affected; ''Borgs, the undead, adult dragons, greater supernatural beings, true robots and androids are immune', NULL, NULL, 'Weakens a foe: the victim goes pale and feeble, his S.D.C., Hit Points and speed are reduced by half, he loses one attack per melee, and his skills are -10%. A caster of levels 1-3 affects one individual per casting; from fourth level he may instead enchant a zone 15 feet (4.6 m) across that affects everyone who enters and remains in it. When the duration lapses, skills and attacks return to normal at once, S.D.C. comes back at 8 per hour and Hit Points at 4 per hour, while the halved speed and feeling of weakness linger for six hours.', 'Life Drain', 'soulmancy', NULL),
  ('Soulmancy: Blood Rain (Panic)', 8, 80, '80 P.P.E. plus 2D6 damage as the caster slashes himself for the blood', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.98-99', 'rifts', 'Up to 100 feet (30.5 m) away per level of the spell caster', 'One melee round per level of the spell caster', 'Horror Factor 15; fear and panic', '15 or higher', 'A 10 foot (3 m) radius per level of the spell caster', NULL, 'Blood pours from the sky over the area. Only the caster''s enemies are affected: any who fail the save panic and flee the bleeding sky, seasoned warriors included, and a crowd becomes a stampede. A fleeing man-at-arms has a 01-15% chance to slip and fall (01-35% for anyone else), taking 1D4 damage and losing 1D4+1 melee actions getting up. Victims run until they are 1D6x10 yards clear of the rain; ordinary civilians run four times as far or hide for 3D6 minutes. Anyone cornered into fighting has no initiative and is -6 on Perception Rolls, -2 melee actions and -2 on all combat rolls, and fights only to get past and keep running. The urge to flee stops with the rain, but the penalties last one more melee round. Useful as a distraction and for breaking enemy ranks.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Consume Soul', 8, 50, '50 P.P.E. plus a soul', NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.99', 'rifts', 'Touch', 'Instant', NULL, 'None for the captured life essence', NULL, NULL, 'Converts a life essence held in a container such as a Soul Crystal, never one in a living being, into usable energy chosen at the casting: 4D6x10 P.P.E., or else 2D6x10 I.S.P., for a mortal or lesser supernatural being, double that for a greater supernatural being and triple for a creature of magic. The energy arrives the next melee round and must be spent within one melee, or moved into an amulet, magic weapon or Energy Sphere. It is a usual step in making Soulmancy weapons and items; once the essence is sealed inside an item it can never be taken back out.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Demon Blade', 8, 40, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.99', 'rifts', 'Self only', 'Two melee rounds (30 seconds) per level of the caster; doubled by an optional sacrifice of an innocent sentient being or good-aligned hero, ten times longer (five minutes per level) by sacrificing a powerful creature of magic or an angel', 'To mortals 4D6+4 Hit Point/S.D.C., or 4D6+1 M.D. to M.D.C. armor, vehicles and constructs; 1D4x10+6 M.D. to creatures of magic; 1D6x10+10 M.D. to supernatural Creatures of Light. Full damage to good alignments, half to selfish, 1D6 to evil', 'Dodge or parry with another weapon', NULL, 'Optional sacrifice to lengthen the duration', 'Calls up a huge, jagged blade of crackling light-blue energy wrapped in a black aura, as though forged from a demon''s own evil essence; the caster picks its form, sometimes a battle axe with a demon''s head. It cuts S.D.C. targets for S.D.C. damage and M.D.C. ones for Mega-Damage. Principled and Scrupulous beings take full damage, Unprincipled and Anarchist ones half, and evil beings only 1D6. It is indestructible and grants +1 to strike, parry and disarm, but disappears if the caster is slain or knocked out.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Restore Soul', 8, 35, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.99', 'rifts', 'Touch', 'Takes 1D6 minutes', NULL, 'None', NULL, NULL, 'The rare reversal: a Soulmancer frees a captured life essence from a Soul Crystal, a Hell Tank, the Soul Pits of Grim Mortis or a similar vessel, though never from a Rune weapon. He must know the true name of the soul''s owner. The soul returns at once to its living body or, if that body is dead, drifts away free and unconsumed.', NULL, 'soulmancy', NULL),
  ('Soulmancy: Blood Lust', 9, 80, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.99-100', 'rifts', '100 foot (30.5 m) radius per level of the caster', 'Three minutes per level of the caster', NULL, 'Standard if the magic is unwanted', NULL, 'Requires slaying an enemy soldier, spy or sympathizer', 'Stirs up the primal rage in everyone within the radius; demons commonly cast it over their own soldiers on the eve of battle. Those affected gain +6 P.S., +8 Spd, +2 to strike and +2 to save vs Horror Factor and feel no fatigue, but turn reckless: -4 to dodge, and -2 to parry and disarm. When it wears off they crash, losing one attack per melee round and half their combat bonuses for 2D6+3 minutes. A second casting on the same group within two hours doubles that crash and its length; a third doubles it again.', NULL, 'soulmancy', NULL),
  ('Soulmancy: River of Blood', 9, 50, NULL, NULL, 'import', 'Rifts World Book 35: Megaverse in Flames p.100', 'rifts', 'Touch or 10 feet (3 m) per level of experience; line of sight required', 'Instant or two melees per level of experience', 'An extra 1D6 per melee round to anyone cut and bleeding; supernatural Bio-Regeneration halved', 'Standard, or -2 if the caster holds some of the target''s blood less than an hour old, even a smear from combat', NULL, NULL, 'Thins the blood so that it will not clot. As an attack, any wound the victim carries bleeds heavily for an extra 1D6 damage every melee round, and a supernatural being regenerates at half the usual rate. Creatures of magic, vampires, Elementals and beings without blood are unaffected. Cast on someone stricken by Deadly Clots, it cures them at once.', NULL, 'soulmancy', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 14 spells rows are in' AS assertion, count(*) AS got, 14 AS want
  FROM spells WHERE name IN ('Soulmancy: Blood Bolt', 'Soulmancy: Read Soul in Object', 'Soulmancy: Toxic Blood', 'Soulmancy: Blood Oath', 'Soulmancy: Bloody Boils', 'Soulmancy: Create Soulmancy Soul Crystal', 'Soulmancy: Inflict Internal Trauma', 'Soulmancy: Life Drain', 'Soulmancy: Blood Rain (Panic)', 'Soulmancy: Consume Soul', 'Soulmancy: Demon Blade', 'Soulmancy: Restore Soul', 'Soulmancy: Blood Lust', 'Soulmancy: River of Blood') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~341-megaverse-in-flames-spells-b.sql');
